package com.bank.anagram;

import java.util.logging.Logger;

// Detects shuffled duplicate account labels for National Bank of India.
public class AnagramChecker {
    private static final Logger log = Logger.getLogger(AnagramChecker.class.getName());

    // Anagram check via 26-int frequency array. O(n), O(1) space.
    public boolean isAnagram(String a, String b) {
        if (a == null || b == null) {
            throw new IllegalArgumentException("inputs must not be null");
        }
        // Normalize: lowercase, keep only letters a-z.
        String x = a.toLowerCase().replaceAll("[^a-z]", "");
        String y = b.toLowerCase().replaceAll("[^a-z]", "");
        if (x.length() != y.length()) {            // length-first guard
            log.info(() -> "'" + a + "' vs '" + b + "' → different length, not anagram");
            return false;
        }
        int[] count = new int[26];
        for (char c : x.toCharArray()) {
            count[c - 'a']++;                      // count up for first
        }
        for (char c : y.toCharArray()) {
            if (--count[c - 'a'] < 0) {            // count down; negative → mismatch
                log.info(() -> "'" + a + "' vs '" + b + "' → NOT anagram");
                return false;
            }
        }
        log.info(() -> "'" + a + "' vs '" + b + "' → IS anagram");
        return true;                               // all counts balanced to zero
    }
}
