package com.bank.anagram;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: screen label pairs for shuffled duplicates.
public class AnagramCheckerDemo {
    private static final Logger log = Logger.getLogger(AnagramCheckerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        AnagramChecker checker = new AnagramChecker();

        log.info(() -> "Result = " + checker.isAnagram("Listen", "Silent"));   // true
        log.info(() -> "Result = " + checker.isAnagram("Rajesh", "Priya"));     // false
        log.info(() -> "Result = " + checker.isAnagram("Debit", "Bited"));      // true
    }
}
